local dir=debug.getinfo(1,'S').source:sub(2):match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local c=require('common');local capture;local output;local forbidden={};local i=1;while i<=#arg do if arg[i]=='--forbidden'then i=i+1;table.insert(forbidden,assert(arg[i]))elseif arg[i]=='--output'then i=i+1;output=assert(arg[i])elseif not capture then capture=arg[i]else error('unexpected argument '..arg[i])end;i=i+1 end;assert(capture,'capture required');local f=assert(io.open(capture,'rb'));local payload=f:read('a');f:close();local matches={};for _,token in ipairs(forbidden)do if payload:find(token,1,true)then table.insert(matches,token)end end;c.write_result(output,{capture=capture,bytes=#payload,matches=matches,passed=#matches==0});if #matches>0 then os.exit(2)end
